#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BUTTON1_PIN = 2; 
const int BUTTON2_PIN = 3; 
const int BUTTON3_PIN = 4; 
const int POT_PIN = A3;    
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000, 
};
int currentNumber = 0;
unsigned long lastChangeTime = 0;
int changeDelay = 1000; 

void setup();
void loop();
void displayNumber(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);
  pinMode(BUTTON3_PIN, INPUT_PULLUP);
  displayNumber(currentNumber);
}
void loop() {
  int potValue = analogRead(POT_PIN);
  changeDelay = map(potValue, 0, 1023, 100, 1000); 
  if (digitalRead(BUTTON1_PIN) == LOW) {
    if (millis() - lastChangeTime > changeDelay) {
      currentNumber++;
      if (currentNumber > 99) currentNumber = 0;
      displayNumber(currentNumber);
      lastChangeTime = millis();
    }
  }
  if (digitalRead(BUTTON2_PIN) == LOW) {
    if (millis() - lastChangeTime > changeDelay) {
      currentNumber--;
      if (currentNumber < 0) currentNumber = 99;
      displayNumber(currentNumber);
      lastChangeTime = millis();
    }
  }
  if (digitalRead(BUTTON3_PIN) == LOW) {
    currentNumber = 0;
    displayNumber(currentNumber);
    while (digitalRead(BUTTON3_PIN) == LOW); 
  }
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
